      .brand-mark {
        display: grid;
        width: 42px;
        height: 42px;
        place-items: center;
        border: 1px solid rgba(244, 201, 107, 0.55);
        border-radius: 14px;
        background: linear-gradient(145deg, rgba(244, 201, 107, 0.92), rgba(116, 212, 255, 0.35));
        box-shadow: 0 12px 36px rgba(244, 201, 107, 0.18);
        color: #14110a;
      }

      .nav-links {
        display: flex;
        align-items: center;
        gap: 1.25rem;
        color: var(--muted);
        font-size: 0.95rem;
        font-weight: 700;
      }

      .nav-links a:hover {
        color: var(--text);
      }

      .nav-actions {
        display: flex;
        align-items: center;
        gap: 0.75rem;
      }

      .icon-button,
      .pill-button,
      .secondary-button {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        border: 1px solid var(--line);
        border-radius: 999px;
        min-height: 44px;
        cursor: pointer;
        font: inherit;
        font-weight: 800;
