        background: rgba(244, 201, 107, 0.1);
        color: var(--accent-strong);
        padding: 0.42rem 0.75rem;
        font-size: 0.78rem;
        font-weight: 900;
        letter-spacing: 0.08em;
        text-transform: uppercase;
