        gap: 0.8rem;
        margin: 0;
        padding: 0;
        list-style: none;
      }

      .metric {
        border: 1px solid var(--line);
        border-radius: var(--radius-sm);
        background: rgba(255, 255, 255, 0.045);
        padding: 1rem;
      }

      .metric strong {
