        box-shadow: var(--shadow);
        padding: 1.35rem;
      }

      .product-orb {
        position: absolute;
        right: 8%;
        bottom: 13%;
        width: min(66%, 330px);
        aspect-ratio: 1;
        border-radius: 50%;
        background:
